import {refreshComponentScripts} from './refresh-component-scripts.mjs';
// Private native-export candidate check; source WordPress receives no submissions.
import assert from 'node:assert/strict';import {mkdtemp,cp,readFile,writeFile,rm} from 'node:fs/promises';import path from 'node:path';import {tmpdir} from 'node:os';import {chromium} from 'playwright';import {extract} from '../../engine/extract.mjs';import {run} from '../../engine/pipeline.mjs';import {serveStatic} from '../../engine/static.mjs';import {visualScore} from '../../engine/verify.mjs';
const generated=process.argv.includes('--generated');
const artifact=path.resolve(process.argv.slice(2).find(arg=>!arg.startsWith('--'))||'artifacts/platform/wpforms-heldout'),temp=await mkdtemp(path.join(tmpdir(),'wpf-choices-'));let browser,server;const cases=[];
try{await cp(path.join(artifact,'project'),temp,{recursive:true});if(!generated)await refreshComponentScripts(temp);const captured=JSON.parse(await readFile(path.join(artifact,'captured-model.json'))),page=captured.pages.find(p=>p.route==='/workshop-interest/'),contract=generated?JSON.parse(await readFile(path.join(temp,'forms.json'))).forms.find(f=>f.provider==='wpforms'&&f.route==='/workshop-interest/'):extract(page.sourceHTML,page.url).sourceForms.find(f=>f.provider==='wpforms');contract.delivery={endpoint:'/choices-test',format:'multipart'};const single=contract.fields.find(f=>f.type==='select'&&!f.multiple),multiple=contract.fields.find(f=>f.type==='select'&&f.multiple);for(const f of [single,multiple])f.options.push({value:'Conservation',label:'Conservation'});const config=JSON.parse(await readFile(path.join(temp,'forms.json')));config.forms=config.forms.map(f=>f.id===contract.id?contract:f);await writeFile(path.join(temp,'forms.json'),JSON.stringify(config));await run(process.execPath,['scripts/build.mjs'],{cwd:temp,timeout:120000});server=await serveStatic(path.join(temp,'output'));browser=await chromium.launch({channel:'chrome'});
 for(const width of [1440,390]){const tab=await browser.newPage({viewport:{width,height:844},reducedMotion:'reduce'});let posts=0,body;await tab.route('**/choices-test',async r=>{posts++;body=r.request().postData();await r.fulfill({contentType:'application/json',body:'{"ok":true}'});});await tab.goto(server.url+'/workshop-interest/',{waitUntil:'networkidle'});await tab.evaluate(()=>document.fonts.ready);const screenshot=path.join(artifact,'choices-candidate-'+width+'.png');await tab.screenshot({path:screenshot,fullPage:true,animations:'disabled'});const pixel=visualScore(await readFile(path.join('work/wpf-heldout','workshop-interest-'+width+'.png')),await readFile(screenshot));assert.ok(pixel>=.99,'Closed widget visual mismatch '+pixel);
 const roots=tab.locator('[data-cloner-choices]'),one=roots.nth(0),many=roots.nth(1),search=many.locator('input.choices__input--cloned');assert.equal(await roots.count(),2);await one.focus();await one.press('ArrowDown');await one.press('End');await one.press('Enter');assert.equal(await one.locator('select').inputValue(),'Conservation');await search.fill('mat');await search.press('Enter');await search.fill('cons');await search.press('Enter');assert.deepEqual(await many.locator('select').evaluate(e=>[...e.selectedOptions].map(o=>o.value)),['Materials','Conservation']);await many.getByRole('button',{name:'Remove Materials'}).click();assert.deepEqual(await many.locator('select').evaluate(e=>[...e.selectedOptions].map(o=>o.value)),['Conservation']);
 for(const f of contract.fields.filter(f=>f.type==='email'))await tab.locator('[data-migration-field-index="'+f.sourceIndex+'"]').fill('fixture@example.test');await tab.locator('form.wpforms-form input[type=radio]').first().check();assert.equal(await tab.locator('form.wpforms-form').evaluate(f=>f.checkValidity()),true);await tab.locator('form.wpforms-form button[type=submit]').click();await tab.waitForFunction(()=>document.querySelector('form.wpforms-form [role=status]')?.textContent.includes('accepted'));assert.equal(posts,1);assert.match(body,/Conservation/);assert.doesNotMatch(body,/search_terms|wpforms\[token\]/);cases.push({width,pixel,authoredOptions:true,keyboard:true,filtering:true,removal:true,interceptedPosts:posts});await tab.close();}
 await writeFile(path.join(artifact,'choices-candidate-check.json'),JSON.stringify({candidateScripts:!generated,cases,sourceSubmissions:0,aiCalls:0},null,2));console.log(JSON.stringify({cases:cases.length,minimumPixel:Math.min(...cases.map(c=>c.pixel))}));
}finally{await browser?.close();await server?.close();await rm(temp,{recursive:true,force:true});}
